"contenttype":"jsjQuery","contents":"document.addEventListener('ESignTxnCompletedWithNotification_WIPMain', (event) => {
 window.latestNotification = event.detail.notification;
 document.querySelector("[data-button-id*='WIPMain_AfterSubmitButton']").click();
});

document.addEventListener('ESignTxnCompletedWithNotification_WIPData', (event) => {
 window.latestNotification = event.detail.notification;
 document.querySelector("[data-button-id*='WIPData_AfterSubmitButton']").click();
});

// List of event types that use the same handler
const eventTypes = [
 "ESignTxnCompletedWithNotification_LotRejectsInProcess",
 "ESignTxnCompletedWithNotification_LotRejectsPostProcess",
 "ESignTxnCompletedWithNotification_LotBinsInProcess",
 "ESignTxnCompletedWithNotification_LotBinsPostProcess",
 "ESignTxnCompletedWithNotification_ValidateCarrier",
 "ESignTxnCompletedWithNotification_SetTestProgram",
 "ESignTxnCompletedWithNotification_Sorting",
 "ESignTxnCompletedWithNotification_LotInProcessSplit",
 "ESignTxnCompletedWithNotification_LotPacking",
 "ESignTxnCompletedWithNotification_SamplingWIPData"
];

const handleESignTxnCompleted = (event) => {
 window.latestNotification = event.detail.notification;
 document.querySelector("[data-button-id*='Activity_AfterSubmitButton']").click();
};

// Register each event type with the same handler
eventTypes.forEach(type => {
 document.addEventListener(type, handleESignTxnCompleted);
});","contentsPath":"","onclickmf":"","documentation":"","refreshOnContextChange":false,"refreshOnContextUpdate":false,"encloseHTMLWithDiv":true
